$ErrorActionPreference = 'Stop'
$env:AWS_PAGER = ''

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

$RoleName = 'ec2-ops'

# Trust policy: who can assume the role
[System.IO.File]::WriteAllText((Join-Path $PWD 'trust.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
'@)

# Permissions policy
[System.IO.File]::WriteAllText((Join-Path $PWD 'policy.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "Ec2StartStopView",
      "Effect": "Allow",
      "Action": [
        "ec2:DescribeAvailabilityZones",
        "ec2:DescribeInstanceStatus",
        "ec2:DescribeInstanceTypes",
        "ec2:DescribeInstances",
        "ec2:DescribeTags",
        "ec2:DescribeVolumes"
      ],
      "Resource": "*"
    },
    {
      "Sid": "Ec2StartStopManage",
      "Effect": "Allow",
      "Action": [
        "ec2:StartInstances",
        "ec2:StopInstances"
      ],
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "aws:ResourceTag/Env": "dev"
        }
      }
    }
  ]
}
'@)

aws iam create-role --role-name $RoleName --assume-role-policy-document file://trust.json --description 'Created with RoleCraft' | Out-Null
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-role" }
$PolicyArn = aws iam create-policy --policy-name "${RoleName}-policy" --policy-document file://policy.json --query Policy.Arn --output text
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-policy" }
aws iam attach-role-policy --role-name $RoleName --policy-arn $PolicyArn
if ($LASTEXITCODE -ne 0) { throw "aws failed: attach-role-policy" }
aws iam attach-role-policy --role-name $RoleName --policy-arn 'arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore'
if ($LASTEXITCODE -ne 0) { throw "aws failed: attach-role-policy" }

# EC2 instances use roles through an instance profile.
aws iam create-instance-profile --instance-profile-name $RoleName | Out-Null
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-instance-profile" }
aws iam add-role-to-instance-profile --instance-profile-name $RoleName --role-name $RoleName
if ($LASTEXITCODE -ne 0) { throw "aws failed: add-role-to-instance-profile" }

Write-Host "Created role $RoleName."
Write-Host "Created instance profile $RoleName."
Write-Host "Created and attached policy ${RoleName}-policy."
